<?php
declare(strict_types=1);
require_once __DIR__.'/helpers/lifecycle-provider-trap.php';
require_once dirname(__DIR__).'/engine/bootstrap.php';
use VoxelSite\{ActionManager,AgentAuth,Database,FileManager,Logger,Migrator,Settings,SiteWorkspace};
use VoxelSite\Agent\{ActorPolicy,BusinessRestAdapter,BusinessStudioAdapter,CanonicalJson,OperationActor,OperationException,ProviderCallPolicy,WorkspaceFiles};
$checks=0;
function restBusinessCheck(bool $ok,string $label):void {global $checks;$checks++;if(!$ok)throw new RuntimeException('FAIL '.$label);echo 'PASS '.$label."\n";}
function restBusinessReject(callable $fn,string $code,string $label):void {try{$fn();}catch(OperationException $e){restBusinessCheck($e->errorCode===$code,$label.' ('.$e->errorCode.')');return;}restBusinessCheck(false,$label);}
restBusinessCheck((new ReflectionMethod(FileManager::class,'__construct'))->getNumberOfParameters()>=2 && (new ReflectionMethod(ActionManager::class,'__construct'))->getNumberOfParameters()>=5,'Disposable workspace and Action roots are supported');
$root=sys_get_temp_dir().'/vs-business-rest-'.bin2hex(random_bytes(6));
foreach(['draft/assets/forms','live/assets/forms','private/actions'] as $dir)mkdir($root.'/'.$dir,0700,true);
$root=realpath($root);
foreach(['VS_TEST_PREVIEW_DIR'=>$root.'/draft','VS_TEST_DOC_ROOT'=>$root.'/live','VS_TEST_ASSETS_DIR'=>$root.'/live/assets','VS_TEST_WORKSPACE_STATE_DIR'=>$root.'/private/workspace','VS_TEST_MUTATION_LOCK'=>$root.'/private/site.lock','VS_TEST_ACTIONS_DIR'=>$root.'/private/actions','VS_TEST_ACTION_SITE_DATA_PATH'=>$root.'/private/site.json'] as $key=>$value)putenv($key.'='.$value);
foreach(['logDir'=>$root.'/private','initialized'=>true] as $key=>$value)(new ReflectionProperty(Logger::class,$key))->setValue(null,$value);
Database::resetInstance();$db=Database::getInstance($root.'/private/studio.db');(new Migrator($db,new Settings($db)))->run();
foreach(['owner','editor','viewer'] as $role)$db->insert('users',['email'=>$role.'@example.invalid','password_hash'=>'fixture','name'=>$role,'role'=>$role,'created_at'=>now(),'updated_at'=>now()]);
$db->update('site_workspace_state',['format'=>2],'id=1');file_put_contents($root.'/draft/.htaccess',SiteWorkspace::ACCESS_MARKER."\nRequire all denied\nDeny from all\n");
$workspace=new SiteWorkspace($db,$root.'/draft',$root.'/live',$root.'/private/workspace',$root.'/live/assets');
$owner=new OperationActor('user',1,null,[],'studio_configured',null);$policy=new ActorPolicy($db);$auth=new AgentAuth($db);
$key=$auth->createKey('Business REST','agent',['tools:invoke','submissions:read']);
restBusinessReject(fn()=>$policy->fromRestCredential($key['id'],'business'),'credential_migration_required','Unbound REST key cannot acquire another account’s identity');
$policy->bindRestCredential($owner,$key['id'],1);
restBusinessCheck(class_exists(BusinessRestAdapter::class),'REST business operations have a shared adapter');
$actor=$policy->fromRestCredential($key['id'],'business');
$services=new BusinessStudioAdapter($db,$workspace);$adapter=new BusinessRestAdapter($db,$workspace,$services);
$form=['id'=>'contact','name'=>'Contact','fields'=>[['name'=>'name','type'=>'text','required'=>true]],'submission'=>['store'=>true],'notifications'=>['email'=>['enabled'=>false]]];
foreach(['draft','live'] as $dir)WorkspaceFiles::write($root.'/'.$dir,'assets/forms/contact.json',CanonicalJson::encode($form));
WorkspaceFiles::write($root.'/live','assets/data/site.json','{"name":"Published business"}');
WorkspaceFiles::write($root.'/draft','assets/data/site.json','{"name":"Private draft"}');
WorkspaceFiles::write($root.'/private','site.json','{"name":"Published business"}');
$action=['id'=>'call-back','name'=>'Call back','description'=>'Call back request','active'=>true,'fields'=>[['name'=>'name','type'=>'text','required'=>true]],'notifications'=>['guest_notify'=>false,'owner_notify'=>false],'companion_tools'=>['cancel_by_code'=>true],'confirmation'=>['code_length'=>6]];
WorkspaceFiles::write($root.'/private/actions','call-back.json',CanonicalJson::encode($action));
$run=fn($body)=>ProviderCallPolicy::runExternal(fn()=>$adapter->invoke($actor,json_decode(json_encode($body),false,32,JSON_THROW_ON_ERROR)));
$before=$workspace->status();
$tools=$adapter->tools($actor,[]);$names=array_column($tools['tools'],'name');
restBusinessCheck(in_array('make_call_back',$names,true) && in_array('submit_form',$names,true),'Published form and dynamic Action tools remain discoverable');
restBusinessCheck(!is_dir($root.'/live/_data'),'Tool discovery creates no business database');
restBusinessCheck($run(['name'=>'get_business_info','arguments'=>(object)[]])['name']==='Published business','Data tools read the published root only');
restBusinessReject(fn()=>$run(['name'=>'get_business_info','arguments'=>(object)['path'=>'../private']]),'invalid_schema','Data tools have closed argument contracts');
$read=$run(['name'=>'get_form_schema','arguments'=>['form_id'=>'contact']]);
$input=['name'=>'submit_form','arguments'=>['form_id'=>'contact','data'=>['name'=>'REST visitor']],'version'=>$read['version'],'request_id'=>'rest-form-submit-001'];
restBusinessReject(fn()=>$run(array_diff_key($input,['request_id'=>true])),'invalid_schema','Real submit requires caller request identity');
restBusinessReject(fn()=>$run(array_diff_key($input,['version'=>true])),'invalid_schema','Real submit requires the reviewed schema version');
$made=$run($input);
restBusinessCheck($made['record_created'] && $run($input)===$made,'REST form acknowledgement retry returns the same stored record');
restBusinessReject(fn()=>$run(array_replace($input,['arguments'=>['form_id'=>'contact','data'=>['name'=>'Different']]])),'idempotency_conflict','Request identity cannot be reused for changed form data');
$actionTool=$tools['tools'][array_search('make_call_back',$names,true)];
$actionInput=['name'=>'make_call_back','action_id'=>$actionTool['action_id'],'arguments'=>['name'=>'Action visitor'],'version'=>$actionTool['version'],'request_id'=>'rest-action-submit-001'];
$madeAction=$run($actionInput);
restBusinessCheck($madeAction['record_created'] && $run($actionInput)===$madeAction,'Dynamic Action execution uses a retained shared receipt');
$cancel=['name'=>'cancel_call-back','action_id'=>'call-back','arguments'=>['confirmation_code'=>$madeAction['confirmation_code']],'version'=>$actionTool['version'],'request_id'=>'rest-action-cancel-001'];
restBusinessCheck($run($cancel)===$run($cancel),'Cancellation also uses its original request identity');
$page=$adapter->submissions($actor,['per_page'=>'1']);$second=$adapter->submissions($actor,['per_page'=>'1','cursor'=>$page['next_cursor']]);
restBusinessCheck(count($page['submissions'])===1 && count($second['submissions'])===1 && $page['submissions'][0]['kind']!==$second['submissions'][0]['kind'],'Mixed inbox uses bounded cross-source keyset pagination');
$formRows=$adapter->submissions($actor,['source'=>'form','form_id'=>'contact']);
restBusinessCheck($formRows['submissions'][0]['source']==='api','REST form records retain their actual source');
restBusinessReject(fn()=>$adapter->submissions($actor,['page'=>'2']),'invalid_schema','Offset pages cannot trigger unbounded historical scans');
restBusinessReject(fn()=>$adapter->submissions($actor,['per_page'=>'100000']),'invalid_schema','Inbox rejects oversized page requests');
restBusinessReject(fn()=>$adapter->submissions($actor,['cursor'=>$page['next_cursor'],'source'=>'form']),'content_conflict','Continuation cannot change inbox filters');
$action['notifications']['guest_notify']=true;$action['fields'][]=['name'=>'email','type'=>'email'];
WorkspaceFiles::write($root.'/private/actions','call-back.json',CanonicalJson::encode($action));
restBusinessReject(fn()=>$run(array_replace($actionInput,['request_id'=>'rest-stale-action-001'])),'content_conflict','Changed Action definition cannot be invoked with a stale discovery version');
$current=$services->actions->get($actor,(object)['action_id'=>'call-back']);
restBusinessReject(fn()=>$run(['name'=>'make_call_back','action_id'=>'call-back','arguments'=>['name'=>'Mail visitor','email'=>'visitor@example.invalid'],'version'=>$current['version'],'request_id'=>'rest-mail-denied-001']),'permission_denied','Legacy tool grant does not silently grant email');
restBusinessCheck($run($actionInput)===$madeAction,'Committed Action retry survives a later definition change');
unlink($root.'/private/actions/call-back.json');unlink($root.'/live/assets/forms/contact.json');
restBusinessCheck($run($actionInput)===$madeAction && $run($input)===$made,'Committed retries survive removal of their original definitions');
$mailKey=$auth->createKey('Explicit mail','owner',['tools:invoke','mail:send']);$policy->bindRestCredential($owner,$mailKey['id'],1);
restBusinessCheck(in_array('mail:send',$policy->fromRestCredential($mailKey['id'],'business')->scopes,true) && !in_array('mail:send',$auth->createKey('Default owner','owner')['scopes'],true),'REST email is an explicit owner-only opt-in');
$db->update('users',['role'=>'editor'],'id=1');
restBusinessReject(fn()=>$policy->require($policy->fromRestCredential($mailKey['id'],'business'),['mail:send']),'permission_denied','Current account demotion removes owner mail authority');
$db->update('users',['role'=>'owner'],'id=1');$db->delete('api_keys','id=?',[$key['id']]);
restBusinessReject(fn()=>$run($input),'credential_migration_required','Revoked REST credentials cannot reuse an already constructed actor');
restBusinessCheck($workspace->status()===$before && ($GLOBALS['lifecycle_provider_attempts']??0)===0,'Business adapters leave website versions unchanged and make no provider requests');
echo "$checks REST business checks passed\n";
